import itertools
n=11
# backtrack with diffs remaining largest first perhaps
def search(seq, used, remdiff):
    if len(seq)==n:
        return seq if not remdiff else None
    # choose next diff maybe largest first
    for d in sorted(remdiff, reverse=True):
        for sign in (1,-1):
            x=seq[-1]+sign*d
            if 0<=x<n and x not in used:
                res=search(seq+[x], used|{x}, remdiff-{d})
                if res: return res
    return None
for start in range(n):
    res=search([start], {start}, set(range(1,n)))
    if res:
        print(res)
        print([abs(res[i+1]-res[i]) for i in range(n-1)])
        break
